function rand() {
  return Math.random().toString(16).substring(2);
}

function hashToType(hash: string, byte: number, total: number): number {
  const index = byte * 2;
  const numberHash = Number.parseInt(hash.slice(index, index + 2), 16);

  return Math.floor((numberHash / 255) * total);
}

function renderColorMask(
  maskId: string,
  color: string,
  props: { [key: string]: string } = {}
): string {
  const _props = Object.keys(props)
    .map((key) => `${key}="${props[key]}"`)
    .join(` `);

  let output = ``;
  output += `<g mask="url(#${maskId})" fill="${color}" ${_props}>`;
  output += `    <rect x="0" y="0" width="264" height="280" />`;
  output += `</g>`;

  return output;
}

